// ============================================
// KONFIGURASI SUMBER SCRAPING
// ============================================

const sources = [
  {
    name: 'glints',
    scrape_url: 'https://glints.com/id/opportunities/jobs/explore',
    base_url: 'https://glints.com'
  },
  {
    name: 'jobindo',
    scrape_url: 'https://jobindo.com/lowongan-kerja',
    base_url: 'https://jobindo.com'
  }
];

return sources.map(s => ({ json: s }));

// ============================================
// SMART PARSER
// Deteksi data terstruktur (Next.js / Inertia)
// Jika tidak ada, fallback ke HTML chunking
// ============================================

const html = $input.first().json.data;
const sourceConfig = $('Daftar Sumber').first().json;
const baseUrl = sourceConfig.base_url || '';

const TYPE_MAP = {
  'FULL_TIME': 'full-time',
  'PART_TIME': 'part-time',
  'CONTRACT': 'contract',
  'INTERNSHIP': 'internship',
  'FREELANCE': 'freelance',
};

// ---- 1. Glints: __NEXT_DATA__ (Next.js SSR) ----
const nextDataMatch = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
if (nextDataMatch) {
  try {
    const data = JSON.parse(nextDataMatch[1]);
    const rawJobs = data?.props?.pageProps?.initialJobs?.jobsInPage || [];
    if (rawJobs.length > 0) {
      const jobs = rawJobs.map(job => {
        const loc = [
          job.citySubDivision?.name,
          job.city?.name,
          job.location?.name
        ].filter(Boolean);
        return {
          _structured: true,
          title: job.title,
          company: job.company?.name || 'Tidak diketahui',
          location: loc.length > 0 ? loc.join(', ') : null,
          source_url: `${baseUrl}/id/opportunities/jobs/-/${job.id}`,
          employment_type: TYPE_MAP[job.type] || null,
          salary_min: job.salaries?.[0]?.minAmount || null,
          salary_max: job.salaries?.[0]?.maxAmount || null,
          tags: [
            job.company?.industry?.name,
            job.educationLevel ? job.educationLevel.toLowerCase() : null,
            job.workArrangementOption ? job.workArrangementOption.toLowerCase() : null
          ].filter(Boolean),
          description_raw: null,
          source_name: sourceConfig.name,
        };
      });
      return jobs.map(j => ({ json: j }));
    }
  } catch (e) { /* parse gagal, lanjut ke metode lain */ }
}

// ---- 2. Inertia.js data-page (Jobindo dll) ----
const inertiaMatch = html.match(/data-page="([^"]*)"/s);
if (inertiaMatch) {
  try {
    const decoded = inertiaMatch[1]
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#039;/g, "'");
    const data = JSON.parse(decoded);
    // Coba pola umum Inertia untuk data loker
    const jobArray = data?.props?.jobs?.data
      || data?.props?.vacancies?.data
      || data?.props?.lowongan?.data
      || null;
    if (Array.isArray(jobArray) && jobArray.length > 0) {
      const jobs = jobArray.map(job => ({
        _structured: true,
        title: job.title || job.name,
        company: job.company?.name || job.company || 'Tidak diketahui',
        location: job.location || job.city || null,
        source_url: job.url
          ? (job.url.startsWith('http') ? job.url : baseUrl + job.url)
          : `${baseUrl}/lowongan/${job.slug || job.id}`,
        employment_type: (job.type || job.employment_type || '')
          .toLowerCase().replace(/_/g, '-') || null,
        salary_min: job.salary_min || null,
        salary_max: job.salary_max || null,
        tags: Array.isArray(job.tags) ? job.tags : (Array.isArray(job.skills) ? job.skills : []),
        description_raw: job.description || null,
        source_name: sourceConfig.name,
      }));
      return jobs.map(j => ({ json: j }));
    }
  } catch (e) { /* parse gagal, fallback ke chunking */ }
}

// ---- 3. Fallback: bersihkan & potong HTML untuk AI extraction ----
let cleaned = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<svg[\s\S]*?<\/svg>/gi, '')
  .replace(/<img[^>]*>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const CHUNK_SIZE = 3000;
const chunks = [];
for (let i = 0; i < cleaned.length; i += CHUNK_SIZE) {
  const chunk = cleaned.substring(i, i + CHUNK_SIZE);
  if (chunk.includes('job') || chunk.includes('loker') || chunk.includes('lowongan') ||
      chunk.includes('vacancy') || chunk.includes('career') || chunk.includes('opportunity') ||
      chunk.includes('developer') || chunk.includes('manager') ||
      chunk.includes('Rp') || chunk.includes('Full') || chunk.includes('Part') ||
      chunk.includes('title') || chunk.includes('company')) {
    chunks.push({
      _structured: false,
      html_chunk: chunk,
      source_name: sourceConfig.name,
      base_url: baseUrl,
      chunk_index: chunks.length,
    });
  }
}

const limited = chunks.slice(0, 10);
if (limited.length === 0) {
  throw new Error(`Tidak ada konten loker ditemukan dari ${sourceConfig.name}`);
}
return limited.map(c => ({ json: c }));

// ============================================
// PARSE AI AGENT EXTRACTION → Normalize jobs
// ============================================

const items = $input.all();
const sourceConfig = $('Daftar Sumber').first().json;
const baseUrl = sourceConfig.base_url || '';
const seen = new Set();
const jobs = [];

for (const item of items) {
  try {
    const content = item.json.output || '';
    let parsed = null;
    try {
      parsed = JSON.parse(content);
    } catch (e) {
      const match = content.match(/\[[\s\S]*\]/);
      if (match) try { parsed = JSON.parse(match[0]); } catch (e2) {}
    }
    if (!Array.isArray(parsed)) continue;

    for (const job of parsed) {
      if (!job.title || !job.source_path) continue;
      const sourceUrl = job.source_path.startsWith('http')
        ? job.source_path : baseUrl + job.source_path;
      if (seen.has(sourceUrl)) continue;
      seen.add(sourceUrl);

      let salaryMin = null, salaryMax = null;
      if (job.salary_text) {
        const nums = job.salary_text.match(/([\d.,]+)/g);
        if (nums && nums.length >= 1) {
          const parseNum = (s) => {
            let n = parseFloat(s.replace(/\./g, '').replace(',', '.'));
            if (job.salary_text.toLowerCase().match(/jt|juta/)) n *= 1000000;
            return Math.round(n);
          };
          salaryMin = parseNum(nums[0]);
          if (nums.length >= 2) salaryMax = parseNum(nums[1]);
        }
      }

      jobs.push({
        title: job.title.trim(),
        company: (job.company || 'Tidak diketahui').trim(),
        location: job.location || null,
        source_url: sourceUrl,
        employment_type: job.employment_type || null,
        salary_min: salaryMin,
        salary_max: salaryMax,
        tags: Array.isArray(job.tags) ? job.tags : [],
        description_raw: null,
        source_name: sourceConfig.name,
      });
    }
  } catch (e) {}
}

if (jobs.length === 0) {
  throw new Error(`AI tidak menemukan lowongan dari ${sourceConfig.name}`);
}
return jobs.map(j => ({ json: j }));

